export type WineType = "red" | "white" | "orange" | "rosé" | "sparkling" | "dessert";

export type Practice =
  | "organic"
  | "biodynamic"
  | "demeter"
  | "natural"
  | "low-intervention"
  | "native-yeast"
  | "unfined"
  | "unfiltered"
  | "no-added-sulfites"
  | "sustainable";

export const PRACTICES: { value: Practice; label: string; blurb: string }[] = [
  { value: "organic", label: "Organic", blurb: "Farmed without synthetic pesticides or herbicides." },
  { value: "biodynamic", label: "Biodynamic", blurb: "Biodynamic farming (Demeter, Biodyvin, or uncertified)." },
  { value: "demeter", label: "Demeter certified", blurb: "Third-party certified biodynamic by Demeter International — the strictest biodynamic standard." },
  { value: "natural", label: "Natural", blurb: "Nothing added, nothing taken away in the cellar." },
  { value: "low-intervention", label: "Low intervention", blurb: "Minimal handling — no fining agents, additives, or corrections." },
  { value: "native-yeast", label: "Native yeast", blurb: "Spontaneous fermentation with wild, ambient yeasts — no lab inoculation." },
  { value: "unfined", label: "Unfined", blurb: "Bottled without fining agents like egg white or isinglass." },
  { value: "unfiltered", label: "Unfiltered", blurb: "Bottled without filtration — expect texture and possible sediment." },
  { value: "no-added-sulfites", label: "No added sulfites", blurb: "Only naturally occurring sulfites from fermentation." },
  { value: "sustainable", label: "Sustainable", blurb: "Certified sustainable farming (LIVE, SIP, HVE, etc.)." },
];

export type Festival = "raw" | "wineFare" | "unfiltered" | "bigWest";

export const FESTIVALS: { value: Festival; label: string; blurb: string }[] = [
  { value: "raw", label: "RAW Wine", blurb: "Isabelle Legeron MW's global fair for low-intervention growers." },
  { value: "wineFare", label: "The Vinguard's WINeFare", blurb: "The Vinguard's WINeFare is a wine tasting and community event that amplifies women's work in the natural wine movement." },
  { value: "unfiltered", label: "Unfiltered Wine Festival", blurb: "Berkeley-based festival celebrating natural, unfiltered wines." },
  { value: "bigWest", label: "Big West", blurb: "California's celebration of natural, low-intervention West Coast wine." },
];

export type Identity = "woman" | "lgbtq" | "poc";

export const IDENTITIES: { value: Identity; label: string; blurb: string }[] = [
  { value: "woman", label: "Woman winemaker", blurb: "Wine made by a woman winemaker or owner-vigneronne." },
  { value: "lgbtq", label: "LGBTQ+ winemaker", blurb: "Wine made by an openly LGBTQ+ winemaker." },
  { value: "poc", label: "Winemaker of color", blurb: "Wine made by a BIPOC winemaker." },
];

export interface Wine {
  id: string;
  name: string;
  producer: string;
  winemaker?: string;
  varietal: string;
  region: string;
  year: number;
  type: WineType;
  body: number;
  sweetness: number;
  acidity: number;
  tannin: number;
  price: number;
  notes: string[];
  practices: Practice[];
  festivals?: Festival[];
  identities?: Identity[];
  pairing: string;
  description: string;
  /** Official winemaker / producer site — where to learn about them. */
  producerUrl?: string;
  /** Direct-to-consumer shop or retailer where the bottle is sold. */
  shopUrl?: string;
}

/** Winemaker's own site when known, else a web search for the producer. */
export function learnMoreUrl(w: Wine): string {
  if (w.producerUrl) return w.producerUrl;
  const q = encodeURIComponent(`${w.producer} winery`);
  return `https://duckduckgo.com/?q=${q}`;
}

/** Direct shop when known, else a Wine-Searcher lookup that lists retailers. */
export function buyUrl(w: Wine): string {
  if (w.shopUrl) return w.shopUrl;
  const slug = `${w.producer} ${w.name}`.trim().replace(/\s+/g, "+");
  return `https://www.wine-searcher.com/find/${encodeURIComponent(slug)}`;
}

/** URL-safe slug derived from a producer name. */
export function producerSlug(producer: string): string {
  return producer
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Find every wine whose producer matches the given slug. */
export function winesByProducerSlug(slug: string): Wine[] {
  return WINES.filter((w) => producerSlug(w.producer) === slug);
}

/**
 * Aggregate every festival a producer appears at across the entire catalog.
 * A producer's different bottlings may be poured at different fairs — this
 * union captures the true cross-listing footprint.
 */
export function festivalsForProducer(producer: string): Festival[] {
  const slug = producerSlug(producer);
  const set = new Set<Festival>();
  for (const w of WINES) {
    if (producerSlug(w.producer) !== slug) continue;
    for (const f of w.festivals ?? []) set.add(f);
  }
  return Array.from(set);
}

/** Human label for a festival value. */
export function festivalLabel(f: Festival): string {
  return FESTIVALS.find((x) => x.value === f)?.label ?? f;
}

