// Dedupe guard: prevents the same producer or bottling from being counted
// twice when new batches/sources are appended. Two normalizations run:
//   • producer identity — strips accents, punctuation, and common suffixes
//     (Winery, Estate, Domaine, Cellars, Vineyards, etc.) so "Broc Cellars"
//     and "Broc Cellars, Inc." collapse to one producer.
//   • bottling identity — normalized producer + normalized cuvée name + year.
// When a later entry collides, its festivals / identities / practices are
// merged into the first occurrence so tags from every source are preserved.
const PRODUCER_STOPWORDS = new Set([
  "winery", "wines", "wine", "cellars", "cellar", "estate", "estates",
  "vineyard", "vineyards", "vignoble", "vignobles", "domaine", "domaines",
  "weingut", "azienda", "agricola", "cantina", "bodega", "bodegas",
  "chateau", "château", "the", "and", "et", "co", "inc", "llc", "ltd",
  "srl", "gmbh", "family", "fils", "pere", "père", "frères", "freres",
  "brothers", "sons", "son", "group",
]);

/**
 * Canonical producer aliases: when two spellings mean the same winery but
 * normalize differently (abbreviations, rebrandings, foreign names), map
 * them to a shared key here so every dedupe pass collapses them together.
 * Values are already-normalized keys.
 */
const PRODUCER_ALIASES: Record<string, string> = {
  "vinguards winefare": "vinguard winefare",
  "vinguard s winefare": "vinguard winefare",
};

function stripDiacritics(s: string): string {
  return s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

/** Expand common winery abbreviations before tokenizing. */
function expandProducerAbbrev(s: string): string {
  return s
    .replace(/\bSt\.?\b/gi, "Saint")
    .replace(/\bSte\.?\b/gi, "Sainte")
    .replace(/\bMt\.?\b/gi, "Mount")
    .replace(/\bDom\.?\b/gi, "Domaine")
    .replace(/\bCh\.?\b/gi, "Chateau")
    .replace(/&/g, " and ");
}

export function normalizeProducer(name: string): string {
  const tokens = stripDiacritics(expandProducerAbbrev(name))
    .toLowerCase()
    // strip possessives (broc's → broc) before generic punctuation strip
    .replace(/'s\b/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((t) => t && !PRODUCER_STOPWORDS.has(t));
  const key = tokens.join(" ");
  return PRODUCER_ALIASES[key] ?? key;
}

export function normalizeBottling(name: string): string {
  return stripDiacritics(name)
    .toLowerCase()
    // strip parenthetical annotations like "(RAW NY)" or "[Magnum]"
    .replace(/[([{][^)\]}]*[)\]}]/g, " ")
    // strip bottle sizes and format words
    .replace(/\b\d+(\.\d+)?\s*(ml|cl|l)\b/g, " ")
    .replace(/\b(magnum|jeroboam|methuselah|half\s*bottle)\b/g, " ")
    // strip trailing 4-digit vintage year — vintage is part of the key already
    .replace(/\b(19|20)\d{2}\b/g, " ")
    // strip common cuvée prefixes so "Cuvée X" collides with "X"
    .replace(/\bcuv[eé]e?\b/g, " ")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Canonical key used to detect duplicate bottlings across imports. */
export function bottlingKey(w: Pick<Wine, "producer" | "name" | "year">): string {
  return `${normalizeProducer(w.producer)}|${normalizeBottling(w.name)}|${w.year}`;
}


function mergeUnique<T>(a: T[] | undefined, b: T[] | undefined): T[] | undefined {
  if (!a && !b) return undefined;
  const set = new Set<T>([...(a ?? []), ...(b ?? [])]);
  return Array.from(set);
}

/**
 * Merge a scalar field from an incoming duplicate row into the canonical
 * entry without silently clobbering a real prior value. Existing wins;
 * conflicts are logged in dev so source data can be reconciled instead of
 * quietly diverging.
 */
function keepFirstScalar<T>(
  field: string,
  existingId: string,
  existing: T | undefined,
  incoming: T | undefined,
): T | undefined {
  if (existing === undefined || existing === null || existing === "") return incoming;
  if (incoming === undefined || incoming === null || incoming === "") return existing;
  if (existing !== incoming && import.meta.env?.DEV) {
    console.warn(
      `[wines] merge conflict on ${field} for ${existingId}: kept "${String(existing)}", ignored "${String(incoming)}"`,
    );
  }
  return existing;
}

const VALID_TYPES: readonly WineType[] = ["red", "white", "orange", "rosé", "sparkling", "dessert"];
const VALID_PRACTICES = new Set<string>(PRACTICES.map((p) => p.value));
const VALID_FESTIVALS = new Set<string>(FESTIVALS.map((f) => f.value));
const VALID_IDENTITIES = new Set<string>(IDENTITIES.map((i) => i.value));

const CURRENT_YEAR = new Date().getFullYear();

function isNonEmptyString(v: unknown): v is string {
  return typeof v === "string" && v.trim().length > 0;
}

function isFiniteNum(v: unknown): v is number {
  return typeof v === "number" && Number.isFinite(v);
}

function inRange(v: unknown, min: number, max: number): v is number {
  return isFiniteNum(v) && v >= min && v <= max;
}

function isValidUrl(v: unknown): boolean {
  if (typeof v !== "string" || !v.trim()) return false;
  try {
    const u = new URL(v);
    return u.protocol === "http:" || u.protocol === "https:";
  } catch {
    return false;
  }
}

/**
 * Validate a Wine row. Returns the errors found so bad imports can be
 * dropped (or surfaced in a form) instead of crashing renders downstream.
 */
export function validateWine(w: unknown): { ok: true; wine: Wine } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  if (!w || typeof w !== "object") {
    return { ok: false, errors: ["row is not an object"] };
  }
  const r = w as Record<string, unknown>;

  if (!isNonEmptyString(r.id)) errors.push("id missing or empty");
  if (!isNonEmptyString(r.producer)) errors.push("producer missing or empty");
  if (!isNonEmptyString(r.name)) errors.push("name missing or empty");
  if (!isNonEmptyString(r.varietal)) errors.push("varietal missing or empty");
  if (!isNonEmptyString(r.region)) errors.push("region missing or empty");
  if (!isNonEmptyString(r.pairing)) errors.push("pairing missing or empty");
  if (!isNonEmptyString(r.description)) errors.push("description missing or empty");
  if (r.winemaker !== undefined && typeof r.winemaker !== "string") {
    errors.push("winemaker must be a string when provided");
  }

  if (!inRange(r.year, 1800, CURRENT_YEAR + 2)) errors.push(`year out of range (got ${String(r.year)})`);
  if (!inRange(r.price, 0, 100000)) errors.push(`price out of range (got ${String(r.price)})`);
  for (const k of ["body", "sweetness", "acidity", "tannin"] as const) {
    if (!inRange(r[k], 0, 10)) errors.push(`${k} must be a number 0–10 (got ${String(r[k])})`);
  }

  if (typeof r.type !== "string" || !VALID_TYPES.includes(r.type as WineType)) {
    errors.push(`type invalid (got ${String(r.type)})`);
  }

  if (!Array.isArray(r.notes) || !r.notes.every((n) => typeof n === "string" && n.trim())) {
    errors.push("notes must be an array of non-empty strings");
  }
  if (!Array.isArray(r.practices) || !r.practices.every((p) => typeof p === "string" && VALID_PRACTICES.has(p))) {
    errors.push("practices contains unknown values");
  }
  if (r.festivals !== undefined) {
    if (!Array.isArray(r.festivals) || !r.festivals.every((f) => typeof f === "string" && VALID_FESTIVALS.has(f))) {
      errors.push("festivals contains unknown values");
    }
  }
  if (r.identities !== undefined) {
    if (!Array.isArray(r.identities) || !r.identities.every((i) => typeof i === "string" && VALID_IDENTITIES.has(i))) {
      errors.push("identities contains unknown values");
    }
  }
  if (r.producerUrl !== undefined && r.producerUrl !== "" && !isValidUrl(r.producerUrl)) {
    errors.push("producerUrl must be an http(s) URL");
  }
  if (r.shopUrl !== undefined && r.shopUrl !== "" && !isValidUrl(r.shopUrl)) {
    errors.push("shopUrl must be an http(s) URL");
  }

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, wine: w as Wine };
}

/**
 * Detect scalar conflicts between a canonical bottling and an incoming
 * duplicate. Same producer + name + year with a different wine type or a
 * dramatically different price is almost always bad source data — merging
 * it would silently corrupt the canonical entry, so we keep the two as
 * separate records instead.
 */
function bottlingConflict(existing: Wine, incoming: Wine): string | null {
  if (existing.type !== incoming.type) {
    return `type ${existing.type} vs ${incoming.type}`;
  }
  const priceGap = Math.abs(existing.price - incoming.price);
  if (priceGap > Math.max(20, existing.price * 0.5)) {
    return `price ${existing.price} vs ${incoming.price}`;
  }
  return null;
}

export function dedupeWines(list: Wine[]): Wine[] {
  const seenId = new Set<string>();
  const byBottling = new Map<string, Wine>();
  const out: Wine[] = [];

  const canonicalProducer = new Map<string, string>();
  const canonicalUrls = new Map<string, { producerUrl?: string }>();

  for (const w of list) {
    const check = validateWine(w);
    if (!check.ok) {
      if (import.meta.env?.DEV) {
        console.warn(
          `[wines] invalid row skipped (id=${String((w as { id?: unknown })?.id)}): ${check.errors.join("; ")}`,
        );
      }
      continue;
    }

    if (seenId.has(w.id)) {
      if (import.meta.env?.DEV) console.warn(`[wines] duplicate id skipped: ${w.id}`);
      continue;
    }

    const prodKey = normalizeProducer(w.producer);

    if (!canonicalProducer.has(prodKey)) {
      canonicalProducer.set(prodKey, w.producer);
      canonicalUrls.set(prodKey, { producerUrl: w.producerUrl });
    } else {
      const canonName = canonicalProducer.get(prodKey)!;
      if (w.producer !== canonName && import.meta.env?.DEV) {
        console.warn(
          `[wines] producer spelling collapsed: "${w.producer}" → "${canonName}"`,
        );
      }
      w.producer = canonName;
      const canon = canonicalUrls.get(prodKey)!;
      if (!canon.producerUrl && w.producerUrl) canon.producerUrl = w.producerUrl;
      else if (canon.producerUrl && !w.producerUrl) w.producerUrl = canon.producerUrl;
      else if (canon.producerUrl && w.producerUrl && canon.producerUrl !== w.producerUrl) {
        if (import.meta.env?.DEV) {
          console.warn(
            `[wines] producer URL conflict for "${canonName}": kept ${canon.producerUrl}, ignored ${w.producerUrl}`,
          );
        }
        w.producerUrl = canon.producerUrl;
      }
    }

    const bottleKey = `${prodKey}|${normalizeBottling(w.name)}|${w.year}`;

    const existing = byBottling.get(bottleKey);
    if (existing) {
      const conflict = bottlingConflict(existing, w);
      if (conflict) {
        if (import.meta.env?.DEV) {
          console.warn(
            `[wines] refusing to merge ${w.id} into ${existing.id} — ${conflict}; keeping both`,
          );
        }
        // Keep both as separate entries — no continue.
      } else {
        existing.festivals = mergeUnique(existing.festivals, w.festivals);
        existing.identities = mergeUnique(existing.identities, w.identities);
        existing.practices = Array.from(new Set([...existing.practices, ...w.practices]));
        existing.notes = Array.from(new Set([...existing.notes, ...w.notes]));
        existing.varietal =
          keepFirstScalar("varietal", existing.id, existing.varietal, w.varietal) ?? existing.varietal;
        existing.region =
          keepFirstScalar("region", existing.id, existing.region, w.region) ?? existing.region;
        existing.winemaker = keepFirstScalar("winemaker", existing.id, existing.winemaker, w.winemaker);
        existing.producerUrl = keepFirstScalar(
          "producerUrl", existing.id, existing.producerUrl, w.producerUrl,
        );
        existing.shopUrl = keepFirstScalar("shopUrl", existing.id, existing.shopUrl, w.shopUrl);
        if (import.meta.env?.DEV) {
          console.warn(
            `[wines] duplicate bottling merged into ${existing.id}: ${w.producer} — ${w.name} ${w.year} (id ${w.id})`,
          );
        }
        continue;
      }
    }

    seenId.add(w.id);
    byBottling.set(bottleKey, w);
    out.push(w);
  }

  // Second pass: propagate festivals, identities, and producer URL across every
  // bottling from the same producer so a Big West entry and a RAW entry for the
  // same winery both show both fairs.
  const byProducer = new Map<
    string,
    { fests: Set<Festival>; ids: Set<Identity>; url?: string }
  >();
  for (const w of out) {
    const key = normalizeProducer(w.producer);
    let agg = byProducer.get(key);
    if (!agg) {
      agg = { fests: new Set(), ids: new Set(), url: undefined };
      byProducer.set(key, agg);
    }
    for (const f of w.festivals ?? []) agg.fests.add(f);
    for (const i of w.identities ?? []) agg.ids.add(i);
    if (!agg.url && w.producerUrl) agg.url = w.producerUrl;
  }
  for (const w of out) {
    const agg = byProducer.get(normalizeProducer(w.producer))!;
    if (agg.fests.size) w.festivals = Array.from(agg.fests);
    if (agg.ids.size) w.identities = Array.from(agg.ids);
    if (!w.producerUrl && agg.url) w.producerUrl = agg.url;
  }

  return out;
}

export const WINES: Wine[] = dedupeWines(WINES_RAW);

/** Also exported for tests / post-ingestion audits of the raw source rows. */
export const WINES_SOURCE: readonly Wine[] = WINES_RAW;

export interface CatalogAudit {
  ok: boolean;
  total: number;
  /** ids that appear on more than one row */
  duplicateIds: string[];
  /** rows failing validateWine — id + the reasons */
  invalid: { id: string; errors: string[] }[];
  /**
   * Bottling keys present more than once. After dedupeWines these may only
   * exist when the rows genuinely conflict (type / price), which is the
   * documented "keep both" behaviour — anything else is a bug.
   */
  duplicateBottlings: { key: string; ids: string[]; conflict: string | null }[];
  /** Producers whose display spelling was not collapsed to one canonical name. */
  producerSpellingSplits: { key: string; names: string[] }[];
}

/**
 * Audit a catalog (built-in, imported, or the merged result of an ingestion)
 * for the three invariants we care about: unique ids, complete/valid required
 * fields, and correct dedupe collision handling.
 */
export function auditCatalog(list: readonly Wine[]): CatalogAudit {
  const idCounts = new Map<string, number>();
  const invalid: { id: string; errors: string[] }[] = [];
  const byKey = new Map<string, Wine[]>();
  const byProducerKey = new Map<string, Set<string>>();

  for (const w of list) {
    const id = String((w as { id?: unknown })?.id ?? "<no id>");
    idCounts.set(id, (idCounts.get(id) ?? 0) + 1);
    const check = validateWine(w);
    if (!check.ok) {
      invalid.push({ id, errors: check.errors });
      continue;
    }
    const key = bottlingKey(w);
    byKey.set(key, [...(byKey.get(key) ?? []), w]);
    const pKey = normalizeProducer(w.producer);
    const names = byProducerKey.get(pKey) ?? new Set<string>();
    names.add(w.producer);
    byProducerKey.set(pKey, names);
  }

  const duplicateIds = Array.from(idCounts.entries())
    .filter(([, n]) => n > 1)
    .map(([id]) => id);

  const duplicateBottlings = Array.from(byKey.entries())
    .filter(([, rows]) => rows.length > 1)
    .map(([key, rows]) => ({
      key,
      ids: rows.map((r) => r.id),
      // Non-null only when every extra row legitimately refused to merge.
      conflict: rows.slice(1).map((r) => bottlingConflict(rows[0], r)).find(Boolean) ?? null,
    }));

  const producerSpellingSplits = Array.from(byProducerKey.entries())
    .filter(([, names]) => names.size > 1)
    .map(([key, names]) => ({ key, names: Array.from(names) }));

  const unexplainedDupBottlings = duplicateBottlings.filter((d) => !d.conflict);

  return {
    ok:
      duplicateIds.length === 0 &&
      invalid.length === 0 &&
      unexplainedDupBottlings.length === 0 &&
      producerSpellingSplits.length === 0,
    total: list.length,
    duplicateIds,
    invalid,
    duplicateBottlings,
    producerSpellingSplits,
  };
}

/* ------------------------------------------------------------------ *
 * Merge analysis — a dry run of dedupeWines that records what changed
 * instead of mutating, so an admin can review every merge decision.
 * ------------------------------------------------------------------ */

export interface FieldChange {
  field: string;
  /** Value kept on the canonical row. */
  before: string;
  /** Value from the incoming duplicate that was ignored (or added). */
  incoming: string;
  /** Value after the merge — same as `before` for scalars, unioned for arrays. */
  after: string;
  /** True when the two values genuinely disagreed (not just an addition). */
  conflict: boolean;
}

export interface MergeRecord {
  kind: "merged" | "kept-both";
  /** Reason the rows were kept separate (kept-both only). */
  reason?: string;
  key: string;
  producer: string;
  name: string;
  year: number;
  canonicalId: string;
  incomingId: string;
  changes: FieldChange[];
}

export interface ProducerSpellingRecord {
  key: string;
  canonical: string;
  ignored: string[];
}

export interface MergeAnalysis {
  merges: MergeRecord[];
  /** Merges where at least one scalar field disagreed. */
  conflictedMerges: MergeRecord[];
  /** Rows refused a merge because type/price conflicted — both kept. */
  keptBoth: MergeRecord[];
  producerSpellings: ProducerSpellingRecord[];
  invalid: { id: string; errors: string[] }[];
  duplicateIds: string[];
}

const SCALAR_MERGE_FIELDS = ["varietal", "region", "winemaker", "producerUrl", "shopUrl"] as const;
const ARRAY_MERGE_FIELDS = ["practices", "notes", "festivals", "identities"] as const;

function fmt(v: unknown): string {
  if (v === undefined || v === null || v === "") return "—";
  return Array.isArray(v) ? v.join(", ") : String(v);
}

/**
 * Replay the dedupe pass over source rows and report every merge decision
 * with its before/after values. Pure: input rows are copied, never mutated.
 */
export function analyzeMerges(list: readonly Wine[]): MergeAnalysis {
  const seenId = new Set<string>();
  const duplicateIds: string[] = [];
  const invalid: { id: string; errors: string[] }[] = [];
  const byBottling = new Map<string, Wine>();
  const canonicalProducer = new Map<string, string>();
  const spellings = new Map<string, Set<string>>();
  const merges: MergeRecord[] = [];

  for (const raw of list) {
    const check = validateWine(raw);
    if (!check.ok) {
      invalid.push({ id: String((raw as { id?: unknown })?.id ?? "<no id>"), errors: check.errors });
      continue;
    }
    const w: Wine = JSON.parse(JSON.stringify(raw));

    if (seenId.has(w.id)) {
      duplicateIds.push(w.id);
      continue;
    }

    const prodKey = normalizeProducer(w.producer);
    if (!canonicalProducer.has(prodKey)) {
      canonicalProducer.set(prodKey, w.producer);
    } else {
      const canon = canonicalProducer.get(prodKey)!;
      if (canon !== w.producer) {
        const set = spellings.get(prodKey) ?? new Set<string>();
        set.add(w.producer);
        spellings.set(prodKey, set);
        w.producer = canon;
      }
    }

    const bottleKey = `${prodKey}|${normalizeBottling(w.name)}|${w.year}`;
    const existing = byBottling.get(bottleKey);

    if (existing) {
      const conflict = bottlingConflict(existing, w);
      const changes: FieldChange[] = [];

      if (conflict) {
        for (const f of ["type", "price"] as const) {
          if (existing[f] !== w[f]) {
            changes.push({
              field: f,
              before: fmt(existing[f]),
              incoming: fmt(w[f]),
              after: fmt(existing[f]),
              conflict: true,
            });
          }
        }
        merges.push({
          kind: "kept-both",
          reason: conflict,
          key: bottleKey,
          producer: w.producer,
          name: w.name,
          year: w.year,
          canonicalId: existing.id,
          incomingId: w.id,
          changes,
        });
        seenId.add(w.id);
        byBottling.set(bottleKey, w);
        continue;
      }

      for (const f of SCALAR_MERGE_FIELDS) {
        const a = existing[f];
        const b = w[f];
        const aEmpty = a === undefined || a === null || a === "";
        const bEmpty = b === undefined || b === null || b === "";
        if (bEmpty) continue;
        if (aEmpty) {
          changes.push({ field: f, before: "—", incoming: fmt(b), after: fmt(b), conflict: false });
          (existing[f] as unknown) = b;
        } else if (a !== b) {
          changes.push({ field: f, before: fmt(a), incoming: fmt(b), after: fmt(a), conflict: true });
        }
      }

      for (const f of ARRAY_MERGE_FIELDS) {
        const a = (existing[f] as string[] | undefined) ?? [];
        const b = (w[f] as string[] | undefined) ?? [];
        const added = b.filter((x) => !a.includes(x));
        if (added.length) {
          changes.push({
            field: f,
            before: fmt(a),
            incoming: fmt(added),
            after: fmt([...a, ...added]),
            conflict: false,
          });
          (existing[f] as unknown) = [...a, ...added];
        }
      }

      merges.push({
        kind: "merged",
        key: bottleKey,
        producer: w.producer,
        name: w.name,
        year: w.year,
        canonicalId: existing.id,
        incomingId: w.id,
        changes,
      });
      continue;
    }

    seenId.add(w.id);
    byBottling.set(bottleKey, w);
  }

  const producerSpellings: ProducerSpellingRecord[] = Array.from(spellings.entries()).map(
    ([key, set]) => ({ key, canonical: canonicalProducer.get(key)!, ignored: Array.from(set) }),
  );

  return {
    merges,
    conflictedMerges: merges.filter((m) => m.kind === "merged" && m.changes.some((c) => c.conflict)),
    keptBoth: merges.filter((m) => m.kind === "kept-both"),
    producerSpellings,
    invalid,
    duplicateIds,
  };
}












